// sage2: the C++ rewrite. Currently runs the starter behaviour plus the M1 gate --
// the ported damage model checked against 600 vectors generated by the Python
// model that was validated on 22,029 in-engine predictions.
#include <cambc.h>
#include <cmath>
#include <cstdint>
#include <iostream>
#include "bot.h"
#include "draft.h"
#include "sim.h"
#include "simvec.h"
#include "survive.h"
#include "nav.h"

namespace {

bool verified = false;

void verify_damage_model() {
    if (verified || cambc::round_number() != 30) return;
    verified = true;

    int n = 0;
    const simvec::Case* t = simvec::cases(n);
    const std::uint64_t start = cambc::fuel_remaining();

    int mismatched = 0;
    double worst_abs = 0.0, worst_rel = 0.0;
    for (int i = 0; i < n; ++i) {
        const double got = sim::predict_damage(t[i].a, t[i].d, t[i].base);
        const double want = t[i].expected;
        const double abs_err = std::fabs(got - want);
        const double rel_err = want != 0.0 ? abs_err / std::fabs(want) : abs_err;
        if (abs_err > worst_abs) worst_abs = abs_err;
        if (rel_err > worst_rel) worst_rel = rel_err;
        if (rel_err > 1e-12 && abs_err > 1e-9) {
            if (mismatched < 5)
                std::cout << "SAGE2 MISMATCH case=" << i << " got=" << got
                          << " want=" << want << std::endl;
            ++mismatched;
        }
    }
    const std::uint64_t end = cambc::fuel_remaining();

    std::cout << "SAGE2 GATE cases=" << n << " mismatched=" << mismatched
              << " worst_abs=" << worst_abs << " worst_rel=" << worst_rel
              << std::endl;
    if (end < start)
        std::cout << "SAGE2 FUEL " << n << " predict_damage calls used "
                  << (start - end) << " (" << (double(start - end) / double(n))
                  << " per call, turn budget " << start << ")" << std::endl;
}

int checks_run = 0, checks_failed = 0;

void expect(bool ok, const char* what) {
    ++checks_run;
    if (!ok) {
        ++checks_failed;
        std::cout << "SAGE2 SURVIVE-FAIL " << what << std::endl;
    }
}

void expect_near(double got, double want, const char* what) {
    expect(std::fabs(got - want) < 1e-9, what);
    if (std::fabs(got - want) >= 1e-9)
        std::cout << "    got=" << got << " want=" << want << std::endl;
}

void verify_survive_model() {
    sim::Unit me;
    me.hp = 1000.0; me.max_hp = 1000.0; me.strength = 70.0;

    // one Golem: 120 strength, range 4, adjacent
    double st[4]; int rg[4], ds[4], kd[4];
    st[0] = 120.0; rg[0] = 4; ds[0] = 1; kd[0] = survive::KIND_CAMP;

    expect_near(survive::incoming_per_turn(me, 1, st, rg, ds, kd), 120.0,
                "golem adjacent, no emblems -> 120/turn");
    expect(survive::turns_to_escape(1, rg, ds, kd, false) == 4,
           "escaping a range-4 camp from melee takes 4 turns");
    expect(survive::turns_to_escape(1, rg, ds, kd, true) == 3,
           "a dash saves one of those turns");

    // the race, which is the whole point: same threat, different health
    sim::Unit low = me; low.hp = 500.0;
    const double inc = 120.0;
    expect(survive::decide(survive::turns_to_death(low, inc), 4, 1.0)
               == survive::ACT_DISENGAGE,
           "at 500hp vs a Golem (ttd 4.2 vs tte 4) we withdraw");
    expect(survive::decide(survive::turns_to_death(me, inc), 4, 1.0)
               == survive::ACT_CARRY_ON,
           "at 1000hp (ttd 8.3) we keep fighting the camp");

    // emblems: Jungle applies to camps, Durability to everything
    sim::Unit tanky = me; tanky.dur = sim::MAG_DURABILITY; tanky.jun = sim::MAG_JUNGLE;
    expect_near(survive::incoming_per_turn(tanky, 1, st, rg, ds, kd),
                120.0 * (1.0 - sim::MAG_DURABILITY) * (1.0 - sim::MAG_JUNGLE),
                "camp damage takes both Durability and Jungle");
    st[0] = 100.0; rg[0] = 1; ds[0] = 1; kd[0] = survive::KIND_CHAMPION;
    expect_near(survive::incoming_per_turn(tanky, 1, st, rg, ds, kd),
                100.0 * (1.0 - sim::MAG_DURABILITY),
                "champion damage takes Durability but NOT Jungle");

    // a champion chases, so walking away does not shed it
    expect(survive::turns_to_escape(1, rg, ds, kd, false) == survive::NO_ESCAPE,
           "without a dash a pursuing champion cannot be shed");
    expect(survive::turns_to_escape(1, rg, ds, kd, true) == 1,
           "with a dash it can");
    // Corrected after sage2 died 51 times in one game: an unescapable chaser used
    // to produce "disengage", which donates free hits to something that moves at
    // our speed. Standing and fighting is strictly better.
    expect(survive::decide(50.0, survive::NO_ESCAPE, 1.0) == survive::ACT_FIGHT,
           "an unescapable chaser means fight, never flee");
    expect(survive::decide(2.0, 1, 1.0) == survive::ACT_DISENGAGE,
           "a shedable threat we are losing to means withdraw");

    // duel prediction: their emblems are invisible, so mitigation is assumed absent
    sim::Unit strong = me; strong.hp = 6000.0; strong.strength = 370.0;
    expect(survive::wins_duel(strong, 370.0, 1000.0, 0.0, 70.0, 1.0),
           "6000hp at 370 strength beats a 1000hp 70-strength enemy");
    sim::Unit frail = me; frail.hp = 300.0; frail.strength = 30.0;
    expect(!survive::wins_duel(frail, 30.0, 6000.0, 0.0, 370.0, 1.0),
           "300hp at 30 strength does not");

    // a champion reaches one tile further than its range, because it closes
    ds[0] = 2;
    expect(survive::incoming_per_turn(tanky, 1, st, rg, ds, kd) > 0.0,
           "a melee champion two tiles away still threatens us");
    ds[0] = 3;
    expect_near(survive::incoming_per_turn(tanky, 1, st, rg, ds, kd), 0.0,
                "three tiles away it does not");

    // out-of-range camps contribute nothing
    st[0] = 120.0; rg[0] = 4; ds[0] = 9; kd[0] = survive::KIND_CAMP;
    expect_near(survive::incoming_per_turn(me, 1, st, rg, ds, kd), 0.0,
                "a camp out of range is not a threat");

    // shields are health for the race, and worth casting only into real damage
    sim::Unit shielded = me; shielded.shield = 250.0;
    expect_near(survive::turns_to_death(shielded, 125.0), 10.0,
                "a shield counts toward time-to-death");
    expect(survive::shield_now(250.0, 180.0, 5, 0.6),
           "cast the shield when 900 damage is inbound over 5 turns");
    expect(!survive::shield_now(250.0, 10.0, 5, 0.6),
           "hold it when only 50 is");
    expect(survive::survives_for(shielded, 180.0, 5.0),
           "1250 effective health survives 5 turns of 180");
    expect(!survive::survives_for(shielded, 180.0, 10.0),
           "it does not survive 10");

    std::cout << "SAGE2 SURVIVE checks=" << checks_run
              << " failed=" << checks_failed << std::endl;
}

}  // namespace

int main() {
    Bot bot;
    while (true) {
        try {
            if (cambc::is_draft()) {
                play_draft();
            } else {
                verify_damage_model();
                if (cambc::round_number() == 31 && checks_run == 0) verify_survive_model();
                bot.play_turn();
            }
        } catch (const std::exception& error) {
            std::cout << "bot error: " << error.what() << std::endl;
        } catch (...) {
            std::cout << "bot error: unknown exception" << std::endl;
        }
        cambc::end_turn();
    }
}
